"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16526"],{31285(e){e.exports=JSON.parse('{"id":"FIN-353","slug":"savings-account","term":"Savings Account","also_known_as":[],"difficulty":"Beginner","definition":"A savings account is a bank account designed for keeping money you do not need for everyday spending, which pays interest on the balance.","explanation":["Savings accounts offer a safe place to build up money while earning some interest. They are commonly used for emergency funds and short-term goals, such as a holiday or a deposit on a home.","Interest rates vary between banks and account types. Instant-access accounts let you withdraw at any time but may pay lower rates. Notice accounts require you to give advance warning before withdrawing, and often pay more. Some accounts offer bonus rates if you make no withdrawals in a month.","For example, if you keep 5,000 in a savings account paying 3.5% a year, you would earn about 175 in interest over a year, slightly more if interest compounds monthly.","Savings accounts are low-risk, and in many countries deposits are protected up to a limit by deposit insurance. However, interest rates are often variable and may not keep pace with inflation, so money kept there for many years can lose purchasing power. It is worth comparing rates regularly, because banks often reduce rates on older accounts while offering better deals to new customers."],"note":"","total":1725,"prev":{"slug":"savings","term":"Savings"},"next":{"slug":"savings-bank","term":"Savings Bank"}}')}}]);